{"ideviceId":"20251230182330096AWE","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<p style="text-align: justify;">En esta actividad puedes practicar el cálculo de errores.</p>
<p><br /></p>
<!-- Cargamos React y ReactDOM desde Internet -->
<p>
<script crossorigin="" src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
<script crossorigin="" src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
</p>
<!-- Cargamos Babel para traducir el código en el navegador -->
<p>
<script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
</p>
<!-- Cargamos Tailwind CSS para el diseño -->
<p>
<script src="https://cdn.tailwindcss.com"></script>
</p>
<!-- Configuración personalizada de Tailwind -->
<p>
<script>
        tailwind.config = {
            theme: {
                extend: {
                    animation: {
                        'bounce-slow': 'bounce 3s infinite',
                        'pulse-slow': 'pulse 4s cubic-bezier(0.4, 0, 0.6, 1) infinite',
                    }
                }
            }
        }
    </script>
</p>
<style>
        /* Ajustes para evitar conflictos con estilos base de eXeLearning */
        body { margin: 0; padding: 0; background-color: #f8fafc; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; }
        #root { width: 100%; }
        /* Efecto de cristal */
        .glass-panel {
            background: rgba(255, 255, 255, 0.95);
            backdrop-filter: blur(10px);
        }
        input[type=number]::-webkit-inner-spin-button, 
        input[type=number]::-webkit-outer-spin-button { 
            -webkit-appearance: none; 
            margin: 0; 
        }
    </style>
<div id="root"></div>
<p>
<script type="text/babel">
        // --- ICONOS (Lucide React portados) ---
        const Icon = ({ path, className, strokeWidth = 2 }) => (
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" className={className}>
                {path}
            </svg>
        );

        const Icons = {
            Ruler: (props) => <Icon {...props} path={<><path d="M6 18h12" /><path d="M6 14v4" /><path d="M10 14v4" /><path d="M14 14v4" /><path d="M18 14v4" /><path d="M6 10h12" /><path d="M6 6v4" /><path d="M10 6v4" /><path d="M14 6v4" /><path d="M18 6v4" /></>} />,
            Scale: (props) => <Icon {...props} path={<><path d="m16 16 3-8 3 8c-.87.65-1.92 1-3 1s-2.13-.35-3-1Z" /><path d="m2 16 3-8 3 8c-.87.65-1.92 1-3 1s-2.13-.35-3-1Z" /><path d="M7 21h10" /><path d="M12 3v18" /><path d="M3 7h2c2 0 5-1 7-2 2 1 5 2 7 2h2" /></>} />,
            Timer: (props) => <Icon {...props} path={<><line x1="10" x2="14" y1="2" y2="2" /><line x1="12" x2="15" y1="14" y2="11" /><circle cx="12" cy="14" r="8" /></>} />,
            Thermometer: (props) => <Icon {...props} path={<><path d="M14 4v10.54a4 4 0 1 1-4 0V4a2 2 0 0 1 4 0Z" /></>} />,
            Beaker: (props) => <Icon {...props} path={<><path d="M4.5 3h15" /><path d="M6 3v16a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2V3" /><path d="M6 14h12" /></>} />,
            ArrowRight: (props) => <Icon {...props} path={<><path d="M5 12h14" /><path d="m12 5 7 7-7 7" /></>} />,
            SkipForward: (props) => <Icon {...props} path={<><polygon points="5 4 15 12 5 20 5 4" /><line x1="19" x2="19" y1="5" y2="19" /></>} />,
            Trophy: (props) => <Icon {...props} path={<><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6" /><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18" /><path d="M4 22h16" /><path d="M10 14.66V17" /><path d="M14 14.66V17" /><path d="M18 2l-7.95 18.9" /><path d="M6 2L13.95 20.9" /><path d="M6 2h12" /></>} />,
            CheckCircle: (props) => <Icon {...props} path={<><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" /><polyline points="22 4 12 14.01 9 11.01" /></>} />,
            XCircle: (props) => <Icon {...props} path={<><circle cx="12" cy="12" r="10" /><line x1="15" x2="9" y1="9" y2="15" /><line x1="9" x2="15" y1="9" y2="15" /></>} />,
            Help: (props) => <Icon {...props} path={<><circle cx="12" cy="12" r="10" /><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3" /><path d="M12 17h.01" /></>} />,
            Calculator: (props) => <Icon {...props} path={<><rect width="16" height="20" x="4" y="2" rx="2" /><line x1="8" x2="16" y1="6" y2="6" /><line x1="16" x2="16" y1="14" y2="18" /><path d="M16 10h.01" /><path d="M12 10h.01" /><path d="M8 10h.01" /><path d="M12 14h.01" /><path d="M8 14h.01" /><path d="M12 18h.01" /><path d="M8 18h.01" /></>} />,
        };

        // --- COMPONENTE VISUAL PARA ESCENARIOS ---
        const ScenarioVisual = ({ type }) => {
            const visuals = {
                length: {
                    color: "text-sky-500",
                    bg: "bg-sky-100",
                    border: "border-sky-200",
                    icon: <Icons.Ruler className="w-16 h-16" strokeWidth={1.5} />,
                    subIcon: <div className="absolute -bottom-2 -right-2 bg-white p-1 rounded-full shadow-sm"><Icons.Beaker className="w-6 h-6 text-sky-400" /></div>
                },
                weight: {
                    color: "text-purple-500",
                    bg: "bg-purple-100",
                    border: "border-purple-200",
                    icon: <Icons.Scale className="w-16 h-16" strokeWidth={1.5} />,
                    subIcon: <div className="absolute -bottom-2 -right-2 bg-white p-1 rounded-full shadow-sm"><div className="w-6 h-6 rounded-full border-2 border-purple-400 bg-purple-200"></div></div>
                },
                time: {
                    color: "text-amber-500",
                    bg: "bg-amber-100",
                    border: "border-amber-200",
                    icon: <Icons.Timer className="w-16 h-16" strokeWidth={1.5} />,
                    subIcon: <div className="absolute -bottom-2 -right-2 bg-white p-1 rounded-full shadow-sm"><Icons.ArrowRight className="w-6 h-6 text-amber-400" /></div>
                },
                temp: {
                    color: "text-rose-500",
                    bg: "bg-rose-100",
                    border: "border-rose-200",
                    icon: <Icons.Thermometer className="w-16 h-16" strokeWidth={1.5} />,
                    subIcon: <div className="absolute -bottom-2 -right-2 bg-white p-1 rounded-full shadow-sm"><div className="w-6 h-6 rounded-full bg-rose-400 animate-pulse"></div></div>
                }
            };

            const theme = visuals[type] || visuals.length;

            return (
                <div className={`relative p-6 rounded-full ${theme.bg} ${theme.border} border-4 shadow-inner flex items-center justify-center mb-4 transition-all duration-500 hover:scale-105`}>
                    <div className={theme.color}>{theme.icon}</div>
                    {theme.subIcon}
                </div>
            );
        };

        // --- LÓGICA PRINCIPAL ---
        const { useState, useEffect } = React;

        const ErrorLab = () => {
            const [problem, setProblem] = useState(null);
            const [userAbs, setUserAbs] = useState('');
            const [userRel, setUserRel] = useState('');
            const [feedback, setFeedback] = useState(null);
            const [streak, setStreak] = useState(0);
            const [showHint, setShowHint] = useState(false);
            const [animateStreak, setAnimateStreak] = useState(false);

            // Escenarios ampliados con tipos para iconos
            const scenarios = [
                { id: 'l1', type: 'length', name: "Medición de una varilla", unit: "cm", min: 5, max: 20, precision: 3, roundTo: 1 },
                { id: 'w1', type: 'weight', name: "Pesaje de reactivo químico", unit: "g", min: 0.5, max: 5, precision: 4, roundTo: 2 },
                { id: 't1', type: 'time', name: "Tiempo de caída libre", unit: "s", min: 2, max: 15, precision: 3, roundTo: 1 },
                { id: 'te1', type: 'temp', name: "Temperatura de fusión", unit: "°C", min: 20, max: 150, precision: 2, roundTo: 0 },
            ];

            const generateProblem = (keepStreak = true) => {
                if (!keepStreak) {
                    setStreak(0);
                }
                const scenario = scenarios[Math.floor(Math.random() * scenarios.length)];
                const rawVal = Math.random() * (scenario.max - scenario.min) + scenario.min;
                const trueVal = parseFloat(rawVal.toFixed(scenario.precision));

                const factor = Math.pow(10, scenario.roundTo);
                let approxVal;

                if (Math.random() > 0.6) {
                    approxVal = Math.round(trueVal * factor) / factor;
                } else {
                    const noise = (Math.random() > 0.5 ? 1 : -1) / factor;
                    approxVal = parseFloat((Math.round(trueVal * factor) / factor + (trueVal === approxVal ? noise : 0)).toFixed(scenario.roundTo));
                }

                if (approxVal === trueVal) {
                    approxVal = trueVal + (1/factor);
                    approxVal = parseFloat(approxVal.toFixed(scenario.precision));
                }

                setProblem({ ...scenario, trueVal, approxVal, uniqueId: Date.now() });
                setUserAbs('');
                setUserRel('');
                setFeedback(null);
                setShowHint(false);
            };

            useEffect(() => {
                generateProblem(true);
            }, []);

            const handleSubmit = (e) => {
                e.preventDefault();
                if (!problem) return;

                const ea = Math.abs(problem.trueVal - problem.approxVal);
                const er = ea / Math.abs(problem.trueVal);
                const erPercent = er * 100;

                const inputAbs = parseFloat(userAbs.replace(',', '.'));
                const inputRel = parseFloat(userRel.replace(',', '.'));
                const tolerance = 0.000001;

                // Tolerancia en relativo un poco más amplia para facilitar redondeos
                const isAbsCorrect = Math.abs(inputAbs - ea) < tolerance;
                const isRelCorrect = Math.abs(inputRel - erPercent) < 0.05; 

                if (isAbsCorrect && isRelCorrect) {
                    setFeedback('correct');
                    setStreak(s => s + 1);
                    setAnimateStreak(true);
                    setTimeout(() => setAnimateStreak(false), 1000);
                } else {
                    setFeedback('incorrect');
                    setStreak(0);
                }
            };

            // Componente de Recta Numérica (Zoom)
            const NumberLine = ({ vReal, vApprox }) => {
                const min = Math.min(vReal, vApprox);
                const max = Math.max(vReal, vApprox);
                const diff = max - min;
                const padding = diff * 2.5; // Más padding para que se vea mejor
                const viewMin = min - padding;
                const viewMax = max + padding;
                const range = viewMax - viewMin;
                const getPos = (val) => ((val - viewMin) / range) * 100;

                return (
                    <div className="relative w-full h-28 mt-4 bg-white/50 rounded-xl border border-slate-200 overflow-hidden shadow-inner">
                        <div className="absolute top-1/2 left-4 right-4 h-0.5 bg-slate-300 transform -translate-y-1/2"></div>
                        {[...Array(21)].map((_, i) => (
                            <div key={i} className={`absolute top-1/2 h-2 w-px transform -translate-y-1/2 ${i % 5 === 0 ? 'h-3 bg-slate-400' : 'bg-slate-200'}`} style={{left: `${i * 5}%`}}></div>
                        ))}

                        {/* Marcador Real */}
                        <div className="absolute top-1/2 transform -translate-y-1/2 flex flex-col items-center z-20 transition-all duration-700 ease-out" style={{ left: `${getPos(vReal)}%` }}>
                            <div className="w-4 h-4 rounded-full bg-emerald-500 ring-4 ring-emerald-100 shadow-sm"></div>
                            <div className="mt-3 px-2 py-0.5 bg-emerald-100 text-emerald-700 text-[10px] font-bold rounded-full border border-emerald-200 shadow-sm whitespace-nowrap">Real</div>
                        </div>

                        {/* Marcador Aprox */}
                        <div className="absolute top-1/2 transform -translate-y-1/2 flex flex-col items-center z-10 transition-all duration-700 ease-out" style={{ left: `${getPos(vApprox)}%` }}>
                             <div className="mb-3 px-2 py-0.5 bg-blue-100 text-blue-700 text-[10px] font-bold rounded-full border border-blue-200 shadow-sm whitespace-nowrap">Medido</div>
                            <div className="w-4 h-4 rounded-full bg-blue-500 ring-4 ring-blue-100 shadow-sm"></div>
                        </div>

                        {/* Linea de Error */}
                        {feedback && (
                            <div className="absolute top-1/2 h-1.5 bg-rose-400/60 rounded-full animate-pulse" style={{ left: `${getPos(min)}%`, width: `${getPos(max) - getPos(min)}%`, transform: 'translateY(-50%)' }}></div>
                        )}
                    </div>
                );
            };

            return (
                <div className="min-h-screen p-4 md:p-8 flex flex-col items-center justify-center font-sans bg-slate-50">

                    {/* --- HEADER --- */}
                    <div className="w-full max-w-4xl flex justify-between items-center mb-6">
                        <div className="flex items-center gap-3">
                            <div className="bg-white p-2.5 rounded-xl shadow-sm border border-slate-100">
                                <Icons.Beaker className="text-indigo-600 w-6 h-6" />
                            </div>
                            <div>
                                <h1 className="text-2xl font-bold bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">LABORATORIO DE ERRORES</h1>
                                <p className="text-sm text-slate-500 font-medium">Precisión y exactitud</p>
                            </div>
                        </div>
                        <div className={`flex items-center gap-3 bg-white pl-4 pr-5 py-2 rounded-full shadow-sm border border-slate-100 transition-all duration-300 ${animateStreak ? 'scale-110 ring-2 ring-amber-200' : ''}`}>
                            <div className="bg-amber-100 p-1.5 rounded-full">
                                <Icons.Trophy className={`w-5 h-5 text-amber-600 ${animateStreak ? 'animate-bounce' : ''}`} />
                            </div>
                            <div className="flex flex-col">
                                <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Racha</span>
                                <span className="text-lg font-black text-slate-700 leading-none">{streak}</span>
                            </div>
                        </div>
                    </div>

                    <div className="w-full max-w-4xl grid md:grid-cols-5 gap-6">

                        {/* --- COLUMNA IZQUIERDA: VISUALIZACIÓN --- */}
                        <div className="md:col-span-2 space-y-4">
                            <div className="glass-panel rounded-2xl p-6 shadow-xl shadow-indigo-100/50 border border-white relative overflow-hidden group">
                                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500"></div>

                                <div className="flex flex-col items-center text-center relative z-10">
                                    <h2 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4">Muestra #{streak + 1}</h2>

                                    {problem && <ScenarioVisual type={problem.type} />}

                                    <h3 className="text-lg font-bold text-slate-700 mb-1">{problem?.name}</h3>
                                    <p className="text-xs text-slate-500 bg-slate-100 px-2 py-1 rounded">Instrumento calibrado en {problem?.unit}</p>
                                </div>

                                {/* Valores */}
                                <div className="mt-8 space-y-3">
                                    <div className="flex justify-between items-center bg-emerald-50/80 p-3 rounded-lg border border-emerald-100">
                                        <div className="text-xs font-semibold text-emerald-600 uppercase">Valor Real</div>
                                        <div className="text-xl font-mono font-bold text-emerald-700">{problem?.trueVal} <span className="text-sm opacity-60">{problem?.unit}</span></div>
                                    </div>
                                    <div className="flex justify-between items-center bg-blue-50/80 p-3 rounded-lg border border-blue-100">
                                        <div className="text-xs font-semibold text-blue-600 uppercase">Valor Medido</div>
                                        <div className="text-xl font-mono font-bold text-blue-700">{problem?.approxVal} <span className="text-sm opacity-60">{problem?.unit}</span></div>
                                    </div>
                                </div>
                            </div>

                            {/* Ayuda */}
                            <button 
                                onClick={() => setShowHint(!showHint)}
                                className="w-full p-3 rounded-xl border border-dashed border-indigo-200 text-indigo-500 hover:bg-indigo-50 hover:border-indigo-300 transition-all flex items-center justify-center gap-2 text-sm font-medium"
                            >
                                <Icons.Help className="w-4 h-4" /> {showHint ? "Ocultar fórmulas" : "Ver fórmulas de ayuda"}
                            </button>

                            {showHint && (
                                <div className="bg-indigo-600 text-white p-4 rounded-xl shadow-lg text-sm animate-in slide-in-from-bottom-2 fade-in">
                                    <ul className="space-y-2">
                                        <li className="flex gap-2"><span className="opacity-50">•</span> <span>E<sub>a</sub> = | Real - Medido |</span></li>
                                        <li className="flex gap-2"><span className="opacity-50">•</span> <span>E<sub>r</sub> = E<sub>a</sub> ÷ Real</span></li>
                                        <li className="flex gap-2"><span className="opacity-50">•</span> <span>% = E<sub>r</sub> × 100</span></li>
                                    </ul>
                                </div>
                            )}
                        </div>

                        {/* --- COLUMNA DERECHA: INTERACCIÓN --- */}
                        <div className="md:col-span-3">
                            <div className="bg-white rounded-2xl shadow-xl shadow-slate-200/50 border border-slate-100 p-6 h-full flex flex-col">

                                {/* Visualizador de Error (Recta) */}
                                <div className="mb-6">
                                    <div className="flex items-center justify-between mb-2">
                                        <label className="text-xs font-bold text-slate-400 uppercase">Análisis Gráfico</label>
                                    </div>
                                    {problem && <NumberLine vReal={problem.trueVal} vApprox={problem.approxVal} />}
                                </div>

                                <form onSubmit={handleSubmit} className="flex-1 flex flex-col justify-end space-y-6">
                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <label className="text-sm font-medium text-slate-700 flex items-center gap-2">
                                                <Icons.Ruler className="w-4 h-4 text-slate-400" /> Error Absoluto
                                            </label>
                                            <div className="relative group">
                                                <input 
                                                    type="number" step="any" required
                                                    value={userAbs} onChange={(e) => setUserAbs(e.target.value)}
                                                    placeholder="0.00"
                                                    disabled={feedback === 'correct'}
                                                    className={`w-full bg-slate-50 border-2 rounded-xl px-4 py-3 font-mono text-lg outline-none transition-all
                                                        ${feedback === 'incorrect' ? 'border-rose-200 bg-rose-50' : 'border-slate-200 focus:border-indigo-400 focus:bg-white'}
                                                    `}
                                                />
                                                <span className="absolute right-4 top-3.5 text-slate-400 text-sm font-medium">{problem?.unit}</span>
                                            </div>
                                        </div>

                                        <div className="space-y-2">
                                            <label className="text-sm font-medium text-slate-700 flex items-center gap-2">
                                                <Icons.Calculator className="w-4 h-4 text-slate-400" /> Error Relativo
                                            </label>
                                            <div className="relative group">
                                                <input 
                                                    type="number" step="any" required
                                                    value={userRel} onChange={(e) => setUserRel(e.target.value)}
                                                    placeholder="0.00"
                                                    disabled={feedback === 'correct'}
                                                    className={`w-full bg-slate-50 border-2 rounded-xl px-4 py-3 font-mono text-lg outline-none transition-all
                                                        ${feedback === 'incorrect' ? 'border-rose-200 bg-rose-50' : 'border-slate-200 focus:border-indigo-400 focus:bg-white'}
                                                    `}
                                                />
                                                <span className="absolute right-4 top-3.5 text-slate-400 text-sm font-bold">%</span>
                                            </div>
                                        </div>
                                    </div>

                                    {/* --- FEEDBACK AREA --- */}
                                    {feedback && (
                                        <div className={`p-4 rounded-xl border-l-4 animate-in fade-in zoom-in-95 ${feedback === 'correct' ? 'bg-emerald-50 border-emerald-500' : 'bg-rose-50 border-rose-500'}`}>
                                            <div className="flex items-start gap-3">
                                                <div className={`mt-1 ${feedback === 'correct' ? 'text-emerald-600' : 'text-rose-600'}`}>
                                                    {feedback === 'correct' ? <Icons.CheckCircle className="w-6 h-6" /> : <Icons.XCircle className="w-6 h-6" />}
                                                </div>
                                                <div className="flex-1">
                                                    <h4 className={`font-bold ${feedback === 'correct' ? 'text-emerald-800' : 'text-rose-800'}`}>
                                                        {feedback === 'correct' ? '¡Medición Precisa!' : 'Revisa tus cálculos'}
                                                    </h4>

                                                    {/* SOLUCIÓN DETALLADA */}
                                                    <div className="mt-2 text-sm space-y-1 font-mono text-slate-700 bg-white/50 p-2 rounded">
                                                        <div className="flex justify-between">
                                                            <span>E<sub>a</sub> =</span>
                                                            <span className="font-bold">{Math.abs(problem.trueVal - problem.approxVal).toFixed(5).replace(/\.?0+$/, '')} {problem.unit}</span>
                                                        </div>
                                                        <div className="flex justify-between border-t border-slate-200 pt-1">
                                                            <span>E<sub>r</sub> (%) =</span>
                                                            <span className="font-bold">{((Math.abs(problem.trueVal - problem.approxVal) / problem.trueVal) * 100).toFixed(3)} %</span>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    )}

                                    {/* --- BOTONES DE ACCIÓN --- */}
                                    <div className="grid grid-cols-2 gap-3 pt-2">
                                        {/* Botón secundario: Saltar (siempre visible si no es correcto) o inactivo */}
                                        {feedback !== 'correct' && (
                                            <button 
                                                type="button"
                                                onClick={() => generateProblem(false)} // false reset streak
                                                className="px-4 py-3 rounded-xl font-semibold text-slate-500 hover:bg-slate-100 hover:text-slate-700 transition-colors flex items-center justify-center gap-2"
                                            >
                                                <Icons.SkipForward className="w-4 h-4" /> Saltar
                                            </button>
                                        )}

                                        {/* Botón principal: Comprobar o Siguiente */}
                                        {feedback === 'correct' ? (
                                            <button 
                                                type="button"
                                                onClick={() => generateProblem(true)}
                                                className="col-span-2 bg-emerald-500 hover:bg-emerald-600 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-emerald-200 transition-all transform hover:scale-[1.02] active:scale-95 flex items-center justify-center gap-2"
                                            >
                                                <Icons.ArrowRight className="w-5 h-5" /> Siguiente Experimento
                                            </button>
                                        ) : (
                                            <button 
                                                type="submit"
                                                className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-indigo-200 transition-all transform hover:scale-[1.02] active:scale-95 flex items-center justify-center gap-2"
                                            >
                                                Comprobar <Icons.ArrowRight className="w-4 h-4 opacity-50" />
                                            </button>
                                        )}
                                    </div>
                                </form>
                            </div>
                        </div>
                    </div>

                    <div className="mt-6 text-slate-400 text-[10px] text-center max-w-lg">
                        Laboratorio virtual diseñado para la práctica de errores
                    </div>
                </div>
            );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<ErrorLab />);
    </script>
</p>
