<style>
        /* ESTILOS DE LA INTERFAZ (MODO ESPÍA / TERMINAL) */
        :root {
            --bg-color: #0f172a; /* Slate 900 */
            --panel-bg: #1e293b; /* Slate 800 */
            --text-main: #4ade80; /* Green 400 */
            --text-dim: #94a3b8; /* Slate 400 */
            --border-color: #16a34a; /* Green 600 */
            --accent-color: #15803d; /* Green 700 */
            --error-color: #ef4444; /* Red 500 */
            --warning-color: #eab308; /* Yellow 500 */
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-main);
            font-family: 'Courier New', Courier, monospace;
            margin: 0;
            padding: 20px;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
        }

        .terminal-container {
            width: 100%;
            max-width: 700px;
            background-color: var(--panel-bg);
            border: 2px solid var(--border-color);
            border-radius: 10px;
            box-shadow: 0 0 20px rgba(74, 222, 128, 0.2);
            overflow: hidden;
        }

        /* HEADER */
        .terminal-header {
            background-color: var(--bg-color);
            padding: 15px;
            border-bottom: 2px solid var(--border-color);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .title {
            font-weight: bold;
            font-size: 1.2rem;
            letter-spacing: 2px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .mode-btn {
            background-color: #334155;
            color: #ccc;
            border: 1px solid #475569;
            padding: 5px 10px;
            border-radius: 4px;
            cursor: pointer;
            font-family: inherit;
            font-size: 0.8rem;
            font-weight: bold;
            transition: all 0.3s;
        }

        .mode-btn.adapted {
            background-color: var(--warning-color);
            color: #000;
            border-color: #ca8a04;
        }

        /* BODY */
        .terminal-body {
            padding: 20px;
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        /* PRODUCT SELECTION */
        .label-text {
            color: var(--text-dim);
            font-size: 0.75rem;
            text-transform: uppercase;
            font-weight: bold;
            margin-bottom: 5px;
            display: block;
        }

        .product-grid {
            display: flex;
            gap: 10px;
            overflow-x: auto;
            padding-bottom: 10px;
        }

        .product-btn {
            background-color: #334155;
            border: 1px solid #475569;
            color: var(--text-dim);
            padding: 10px;
            border-radius: 6px;
            cursor: pointer;
            min-width: 90px;
            display: flex;
            flex-direction: column;
            align-items: center;
            transition: all 0.2s;
        }

        .product-btn:hover {
            opacity: 1;
            background-color: #475569;
        }

        .product-btn.active {
            background-color: rgba(22, 163, 74, 0.3);
            border-color: var(--text-main);
            color: var(--text-main);
            transform: scale(1.05);
            box-shadow: inset 0 0 10px rgba(74, 222, 128, 0.2);
        }

        .icon-large { font-size: 1.5rem; margin-bottom: 5px; }

        /* INPUT AREA GRID */
        .data-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
        }

        @media (max-width: 600px) {
            .data-grid { grid-template-columns: 1fr; }
        }

        .panel {
            background-color: rgba(15, 23, 42, 0.5);
            padding: 15px;
            border-radius: 6px;
            border: 1px solid #334155;
        }

        .panel-title {
            color: var(--text-main);
            font-weight: bold;
            border-bottom: 1px solid #14532d;
            padding-bottom: 5px;
            margin-bottom: 15px;
            font-size: 0.9rem;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        input {
            width: 100%;
            background-color: #1e293b;
            border: 1px solid #14532d;
            color: white;
            padding: 8px;
            border-radius: 4px;
            font-family: inherit;
            font-size: 1rem;
            text-align: right;
            box-sizing: border-box; /* Importante para el width */
        }

        input:focus {
            outline: none;
            border-color: var(--text-main);
            box-shadow: 0 0 5px var(--text-main);
        }

        .verify-btn {
            width: 100%;
            background-color: var(--accent-color);
            color: white;
            border: none;
            padding: 12px;
            border-radius: 4px;
            font-family: inherit;
            font-weight: bold;
            cursor: pointer;
            margin-top: 15px;
            transition: background 0.3s;
            text-transform: uppercase;
        }

        .verify-btn:hover {
            background-color: #166534;
        }

        /* FEEDBACK AREA */
        .feedback-box {
            padding: 15px;
            border-radius: 6px;
            border-left: 4px solid;
            display: none; /* Oculto por defecto */
            animation: slideUp 0.3s ease-out;
        }

        .feedback-box.success {
            background-color: rgba(22, 163, 74, 0.2);
            border-color: var(--text-main);
            color: #dcfce7;
        }

        .feedback-box.error {
            background-color: rgba(239, 68, 68, 0.2);
            border-color: var(--error-color);
            color: #fee2e2;
        }

        .feedback-box.warning {
            background-color: rgba(234, 179, 8, 0.2);
            border-color: var(--warning-color);
            color: #fef9c3;
        }

        @keyframes slideUp {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .footer {
            background-color: var(--bg-color);
            padding: 5px;
            text-align: center;
            font-size: 0.6rem;
            color: var(--text-dim);
            border-top: 1px solid #14532d;
        }

    </style>
<div class="terminal-container"><!-- Header -->
<div class="terminal-header">
<div class="title"><span style="color: var(--text-main);">🛡️ GAIA VERIFIER</span> <span style="font-size: 0.7rem; margin-top: 4px;">v1.0</span></div>
<button id="modeBtn" class="mode-btn" onclick="toggleMode()">MODO ESTÁNDAR</button></div>
<div class="terminal-body"><!-- 1. Selección de Producto -->
<div><span class="label-text">1. SELECCIONA EL OBJETIVO ANALIZADO</span>
<div class="product-grid" id="productGrid"><!-- Se rellena con JS --></div>
</div>
<div class="data-grid"><!-- Panel Izquierdo: Datos de la Ficha -->
<div class="panel">
<div class="panel-title">🔒 DATOS DE TU FICHA</div>
<div style="margin-bottom: 15px;"><span class="label-text">TU APUESTA (Estimación)</span>
<div style="display: flex; align-items: center; gap: 5px;"><input type="number" id="userGuess" placeholder="0" /> <span style="color: #64748b;">L</span></div>
</div>
<div style="background: rgba(20, 83, 45, 0.3); padding: 10px; border-radius: 4px; text-align: center; border: 1px dashed var(--accent-color);"><span class="label-text">DATO REAL (SISTEMA)</span>
<div id="realDataDisplay" style="font-size: 1.5rem; font-weight: bold; letter-spacing: 2px;">560 L</div>
</div>
</div>
<!-- Panel Derecho: Cálculos -->
<div class="panel">
<div class="panel-title">🧮 TUS CÁLCULOS</div>
<div style="margin-bottom: 15px;"><span class="label-text" id="absLabel">TU ERROR ABSOLUTO</span> <input type="number" id="inputAbs" placeholder="¿Cuánto te ha dado?" /></div>
<div id="relContainer" style="margin-bottom: 15px;"><span class="label-text">TU ERROR RELATIVO (%)</span> <input type="number" id="inputRel" placeholder="Resultado final" /></div>
<button class="verify-btn" onclick="verifyData()">🔄 VERIFICAR AHORA</button></div>
</div>
<!-- Área de Feedback -->
<div id="feedbackBox" class="feedback-box"><strong id="feedbackTitle"></strong>
<p id="feedbackText" style="margin: 5px 0 0 0; font-size: 0.9rem; white-space: pre-line;"></p>
</div>
</div>
<div class="footer" id="footerText">SISTEMA OPERATIVO GAIA // CONEXIÓN SEGURA // MODO INGENIERÍA ACTIVADO</div>
</div>
<p>
<script>
    // --- BASE DE DATOS TOP SECRET ---
    const database = [
        { id: 'orange', name: 'Naranja (1 Kg)', real: 560, icon: '🍊' },
        { id: 'milk', name: 'Leche (1 L)', real: 1020, icon: '🥛' },
        { id: 'rice', name: 'Arroz (1 Kg)', real: 2497, icon: '🍚' },
        { id: 'sheep', name: 'Carne Oveja (1 Kg)', real: 10412, icon: '🥩' },
        { id: 'choco', name: 'Chocolate (1 Kg)', real: 17196, icon: '🍫' }
    ];

    // Estado Global
    let currentProduct = database[0];
    let isAdaptedMode = false;

    // Inicialización
    function init() {
        renderProductButtons();
        updateUI(); // Se llama para establecer el estado inicial de la interfaz
    }

    // Renderizar botones de productos
    function renderProductButtons() {
        const grid = document.getElementById('productGrid');
        grid.innerHTML = '';
        database.forEach(prod => {
            const btn = document.createElement('button');
            btn.className = `product-btn ${prod.id === currentProduct.id ? 'active' : ''}`;
            btn.onclick = () => selectProduct(prod);
            btn.innerHTML = `
                <span class="icon-large">${prod.icon}</span>
                <span style="font-size:0.7rem; font-weight:bold;">${prod.name}</span>
            `;
            grid.appendChild(btn);
        });
    }

    function selectProduct(prod) {
        currentProduct = prod;
        renderProductButtons();
        updateUI(); // Actualizamos UI para mostrar datos del nuevo producto
    }

    function toggleMode() {
        isAdaptedMode = !isAdaptedMode;
        updateUI(); // Actualizamos UI para reflejar cambio de modo
    }

    // Función Central para actualizar la Interfaz
    function updateUI() {
        // 1. Actualizar elementos dependientes del MODO
        const btn = document.getElementById('modeBtn');
        const relContainer = document.getElementById('relContainer');
        const absLabel = document.getElementById('absLabel');
        const footer = document.getElementById('footerText');

        if (isAdaptedMode) {
            btn.innerText = "MODO ACCESO";
            btn.classList.add('adapted');
            relContainer.style.display = 'none';
            absLabel.innerText = "TU RESTA (DIFERENCIA)";
            footer.innerText = "SISTEMA OPERATIVO GAIA // CONEXIÓN SEGURA // MODO ACCESIBILIDAD ACTIVADO";
        } else {
            btn.innerText = "MODO ESTÁNDAR";
            btn.classList.remove('adapted');
            relContainer.style.display = 'block';
            absLabel.innerText = "TU ERROR ABSOLUTO";
            footer.innerText = "SISTEMA OPERATIVO GAIA // CONEXIÓN SEGURA // MODO INGENIERÍA ACTIVADO";
        }

        // 2. Actualizar elementos dependientes del PRODUCTO
        document.getElementById('realDataDisplay').innerText = `${currentProduct.real} L`;

        // 3. Limpiar feedback anterior
        resetFeedback();
    }

    function resetFeedback() {
        const box = document.getElementById('feedbackBox');
        box.style.display = 'none';
        box.className = 'feedback-box';
    }

    function verifyData() {
        const userGuess = document.getElementById('userGuess').value;
        const inputAbs = document.getElementById('inputAbs').value;
        const inputRel = document.getElementById('inputRel').value;

        // Validación de campos vacíos
        if (!userGuess || !inputAbs) {
            showFeedback('warning', '⚠️ DATOS INCOMPLETOS', 'Por favor, introduce tu estimación y tu resta.');
            return;
        }

        if (!isAdaptedMode && !inputRel) {
            showFeedback('warning', '⚠️ DATOS INCOMPLETOS', 'Falta el cálculo del porcentaje (Error Relativo).');
            return;
        }

        // 1. Cálculos del Sistema
        const guessVal = parseFloat(userGuess);
        const realAbs = Math.abs(currentProduct.real - guessVal);
        const realRel = (realAbs / currentProduct.real) * 100;

        // 2. Verificación Absoluta (Resta)
        const studentAbs = parseFloat(inputAbs);
        const isAbsCorrect = Math.abs(studentAbs - realAbs) < 1; // Tolerancia 1

        // 3. Verificación Relativa (Porcentaje)
        let isRelCorrect = true;
        if (!isAdaptedMode) {
            const studentRel = parseFloat(inputRel);
            isRelCorrect = Math.abs(studentRel - realRel) < 0.5; // Tolerancia 0.5%
        }

        // 4. Resultado Final
        if (isAbsCorrect && isRelCorrect) {
            showFeedback('success', '✅ CALIBRACIÓN EXITOSA', 'Tus cálculos son exactos. Excelente trabajo, agente.');
        } else {
            let msg = '';
            if (!isAbsCorrect) {
                msg += `> Tu resta está mal.\nDato Real (${currentProduct.real}) - Tu Apuesta (${guessVal}) debería ser ${realAbs}.\n`;
            }
            if (!isAdaptedMode && !isRelCorrect) {
                msg += `> Tu porcentaje no coincide. Revisa la fórmula del Error Relativo.`;
            }
            showFeedback('error', '❌ ERROR DE SINCRONIZACIÓN', msg);
        }
    }

    function showFeedback(type, titleText, bodyText) {
        const box = document.getElementById('feedbackBox');
        const title = document.getElementById('feedbackTitle');
        const text = document.getElementById('feedbackText');

        box.className = `feedback-box ${type}`;
        box.style.display = 'block';
        title.innerText = titleText;
        text.innerText = bodyText;
    }

    // Arrancar
    init();

</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

