        }

        .container {
            width: 100%;
            max-width: 900px;
            background-color: var(--bg-panel);
            border: 2px solid var(--border-red);
            box-shadow: 0 0 30px rgba(139, 0, 0, 0.2);
            border-radius: 4px;
            overflow: hidden;
        }

        .header {
            background: linear-gradient(90deg, #300 0%, #000 100%);
            padding: 15px 20px;
