            text-shadow: 0 0 5px var(--border-red);
        }

        .badge {
            background: var(--border-red);
            color: white;
            padding: 2px 8px;
            font-size: 0.8rem;
            border-radius: 2px;
        }

        .content {
            padding: 20px;
        }

        /* TABLA */
        .evidence-table {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 20px;
        }

        .evidence-table th {
            text-align: left;
            padding: 10px;
            color: var(--text-dim);
            font-size: 0.8rem;
