<script type="text/babel">

    const { useState, useEffect } = React;

    function ForensicVerifier() {
        const [rows, setRows] = useState([
            { id: 1, name: '', mass: '', factor: '', userTotal: '', status: 'neutral' }
        ]);
        const [userGrandTotal, setUserGrandTotal] = useState('');
        const [verificationStatus, setVerificationStatus] = useState('idle'); // idle, pass, fail
        const [message, setMessage] = useState('');

        // Añadir fila
        const addRow = () => {
            const newId = rows.length > 0 ? Math.max(...rows.map(r => r.id)) + 1 : 1;
            setRows([...rows, { id: newId, name: '', mass: '', factor: '', userTotal: '', status: 'neutral' }]);
        };

        // Eliminar fila
        const deleteRow = (id) => {
            if (rows.length === 1) return;
            setRows(rows.filter(r => r.id !== id));
        };

        // Actualizar datos de fila
        const updateRow = (id, field, value) => {
            setRows(rows.map(row => 
                row.id === id ? { ...row, [field]: value, status: 'neutral' } : row
            ));
            setVerificationStatus('idle');
        };

        // LÓGICA DE VERIFICACIÓN
        const verifyEvidence = () => {
            let allCorrect = true;
            let totalRealCalc = 0;
            let errors = [];

            // 1. Verificar fila a fila
            const checkedRows = rows.map(row => {
                const mass = parseFloat(row.mass.replace(',', '.'));
                const factor = parseFloat(row.factor.replace(',', '.'));
                const userVal = parseFloat(row.userTotal.replace(',', '.'));

                if (isNaN(mass) || isNaN(factor) || isNaN(userVal)) {
                    return { ...row, status: 'error' }; // Faltan datos
                }

                // Cálculo real
                const realVal = mass * factor;
                totalRealCalc += realVal;

                // Comprobación con tolerancia
                const diff = Math.abs(realVal - userVal);

                // Detectar error de magnitud (gramos vs kg)
                if (mass > 50) {
                    errors.push(`⚠️ ALERTA EN ${row.name || 'Fila ' + row.id}: Masa sospechosa (${mass}). ¿Has olvidado convertir a Kg?`);
                }

                if (diff < 1) {
                    return { ...row, status: 'success' };
                } else {
                    allCorrect = false;
                    return { ...row, status: 'error' };
                }
            });

            setRows(checkedRows);

            // 2. Verificar Total Final
            const userTotalFloat = parseFloat(userGrandTotal.replace(',', '.'));

            if (isNaN(userTotalFloat)) {
                setMessage("⚠️ Introduce tu SUMA TOTAL para finalizar la auditoría.");
                setVerificationStatus('fail');
                return;
            }

            const totalDiff = Math.abs(totalRealCalc - userTotalFloat);

            if (allCorrect && totalDiff < 2) {
                setVerificationStatus('pass');
                setMessage("✅ AUDITORÍA APROBADA. Los cálculos forenses son exactos. Caso cerrado.");
            } else {
                setVerificationStatus('fail');
                if (errors.length > 0) {
                    setMessage(errors.join("\n"));
                } else if (!allCorrect) {
                    setMessage("❌ ERROR EN FILAS: Algunas multiplicaciones no coinciden. Revisa las celdas rojas.");
                } else {
                    setMessage(`❌ ERROR DE SUMA: Las filas están bien, pero tu total (${userTotalFloat}) no coincide con la suma real (${totalRealCalc.toFixed(2)}). Revisa la suma.`);
                }
            }
        };

        return (
            <div className="container">
                <div className="header">
                    <div className="title">GAIA FORENSIC <span style={{fontSize:'0.8rem'}}>v2.0</span></div>
                    <span className="badge">SOLO USO INTERNO</span>
                </div>

                <div className="content">
                    <table className="evidence-table">
                        <thead>
                            <tr>
                                <th style={{width:'30%'}}>EVIDENCIA (Ingrediente)</th>
                                <th style={{width:'15%'}}>MASA (Kg)</th>
                                <th style={{width:'15%'}}>FACTOR (L/Kg)</th>
                                <th style={{width:'20%'}}>TU CÁLCULO (L)</th>
                                <th style={{width:'5%'}}></th>
                            </tr>
                        </thead>
                        <tbody>
                            {rows.map((row) => (
                                <tr key={row.id}>
                                    <td>
                                        <input 
                                            type="text" 
                                            placeholder="Ej: Tomate"
                                            value={row.name}
                                            onChange={(e) => updateRow(row.id, 'name', e.target.value)}
                                        />
                                    </td>
                                    <td>
                                        <input 
                                            type="number" 
                                            placeholder="0.000"
                                            value={row.mass}
                                            onChange={(e) => updateRow(row.id, 'mass', e.target.value)}
                                        />
                                        {row.mass > 10 && <div className="hint" style={{color:'orange'}}>⚠ ¿Seguro?</div>}
                                    </td>
                                    <td>
                                        <input 
                                            type="number" 
                                            placeholder="0"
                                            value={row.factor}
                                            onChange={(e) => updateRow(row.id, 'factor', e.target.value)}
                                        />
                                    </td>
                                    <td>
                                        <input 
                                            type="number" 
                                            placeholder="Resultado"
                                            className={row.status === 'success' ? 'success' : row.status === 'error' ? 'error' : ''}
                                            value={row.userTotal}
                                            onChange={(e) => updateRow(row.id, 'userTotal', e.target.value)}
                                        />
                                    </td>
                                    <td>
                                        <button className="btn-delete" onClick={() => deleteRow(row.id)}>×</button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>

                    <button className="btn btn-add" onClick={addRow}>+ AÑADIR EVIDENCIA</button>

                    <div className="summary-box">
                        <div style={{width: '60%'}}>
                            <label style={{color: '#999', fontSize: '0.9rem'}}>INTRODUCE TU SUMA TOTAL:</label>
                            <input 
                                type="number" 
                                style={{fontSize: '1.5rem', fontWeight: 'bold', marginTop: '10px'}}
                                placeholder="Total de tu ficha..."
                                value={userGrandTotal}
                                onChange={(e) => {setUserGrandTotal(e.target.value); setVerificationStatus('idle')}}
                            />
                        </div>
                        <div>
                            <button className="btn" style={{backgroundColor: '#c0392b', border: 'none', padding: '15px 30px', fontSize:'1.1rem'}} onClick={verifyEvidence}>
                                🔍 EJECUTAR AUDITORÍA
                            </button>
                        </div>
                    </div>

                    <div className={`feedback-area ${verificationStatus !== 'idle' ? 'visible' : ''} ${verificationStatus === 'pass' ? 'correct' : 'incorrect'}`}>
                        <strong style={{display:'block', marginBottom:'5px'}}>
                            {verificationStatus === 'pass' ? 'ACCESO CONCEDIDO' : 'ACCESO DENEGADO'}
                        </strong>
                        <span style={{whiteSpace: 'pre-line'}}>{message}</span>
                    </div>

                </div>
            </div>
        );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<ForensicVerifier />);

</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

