<p>
<script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
<script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
<script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
<script src="https://unpkg.com/lucide@latest"></script>
</p>
<style>
        :root {
            --bg-deep: #001a33;
            --bg-panel: #002b4d;
            --text-neon: #00ffff;
            --text-white: #e6f2ff;
            --border-neon: #008fb3;
            --accent-gold: #ffd700;
            --error: #ff3333;
            --success: #00ffaa;
        }

        body {
            background-color: var(--bg-deep);
            color: var(--text-white);
            font-family: 'Courier New', Courier, monospace;
            margin: 0;
            padding: 20px;
            min-height: 100vh;
            background-image: 
                linear-gradient(rgba(0, 255, 255, 0.05) 1px, transparent 1px),
                linear-gradient(90deg, rgba(0, 255, 255, 0.05) 1px, transparent 1px);
            background-size: 30px 30px;
        }

        .lab-container {
            max-width: 1000px;
            margin: 0 auto;
            border: 2px solid var(--border-neon);
            box-shadow: 0 0 20px rgba(0, 255, 255, 0.2);
            background: var(--bg-panel);
            border-radius: 8px;
            overflow: hidden;
        }

        .header {
            background: linear-gradient(90deg, #001a33 0%, #004080 100%);
            padding: 15px 25px;
            border-bottom: 2px solid var(--border-neon);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .brand {
            font-size: 1.5rem;
            font-weight: bold;
            color: var(--text-neon);
            text-transform: uppercase;
            letter-spacing: 2px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        /* TABLA DE EXPERIMENTOS */
        .experiment-area {
            padding: 20px;
            overflow-x: auto;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            min-width: 800px;
        }

        th {
            text-align: left;
            color: var(--text-neon);
            padding: 10px;
            border-bottom: 1px solid var(--border-neon);
            font-size: 0.9rem;
        }

        td {
            padding: 10px;
            vertical-align: middle;
            border-bottom: 1px solid rgba(0, 255, 255, 0.1);
        }

        /* INPUTS ESTILIZADOS */
        input {
            background: rgba(0, 0, 0, 0.3);
            border: 1px solid var(--border-neon);
            color: white;
            padding: 8px;
            font-family: inherit;
            width: 100%;
            box-sizing: border-box;
            text-align: center;
            transition: all 0.3s;
        }

        input:focus {
            outline: none;
            background: rgba(0, 255, 255, 0.1);
            box-shadow: 0 0 10px var(--text-neon);
        }

        input.valid { border-color: var(--success); color: var(--success); }
        input.invalid { border-color: var(--error); color: var(--error); }

        .fraction-group {
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .fraction-divider {
            font-size: 1.2rem;
            color: var(--text-neon);
        }

        /* BOTONES */
        .btn {
            padding: 10px 20px;
            cursor: pointer;
            font-weight: bold;
            text-transform: uppercase;
            border: none;
            border-radius: 4px;
            transition: 0.3s;
        }

        .btn-add {
            background: transparent;
            border: 1px dashed var(--text-neon);
            color: var(--text-neon);
            width: 100%;
            margin-top: 10px;
        }
        .btn-add:hover { background: rgba(0, 255, 255, 0.1); }

        .btn-verify {
            background: var(--text-neon);
            color: #000;
            box-shadow: 0 0 15px var(--text-neon);
            font-size: 1.1rem;
            width: 100%;
        }
        .btn-verify:hover { background: #fff; box-shadow: 0 0 25px #fff; }

        .btn-del {
            background: transparent; color: var(--error); border:none; font-size:1.2rem;
        }

        /* PANEL DE RESULTADOS */
        .results-panel {
            background: #001a33;
            padding: 20px;
            border-top: 2px solid var(--border-neon);
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
        }

        .status-box {
            border: 1px solid var(--border-neon);
            padding: 15px;
            border-radius: 4px;
            text-align: center;
        }

        .big-stat {
            font-size: 2.5rem;
            font-weight: bold;
            color: var(--text-white);
            display: block;
            margin: 10px 0;
        }

        .status-msg { font-size: 0.9rem; min-height: 40px; }
        .pass { color: var(--success); text-shadow: 0 0 5px var(--success); }
        .fail { color: var(--error); text-shadow: 0 0 5px var(--error); }

    </style>
<div id="root"></div>
<p>
<script type="text/babel">
    const { useState, useEffect } = React;
    const { FlaskConical, Atom, RefreshCw, Trash2, Check, AlertTriangle } = lucide;

    function AlchemyLab() {
        // Estado inicial de las filas (Ingredientes)
        const [rows, setRows] = useState([
            { id: 1, name: '', origMass: '', num: '', den: '', factor: '', userMass: '', userHuella: '', status: 'neutral' }
        ]);

        const [simulationResult, setSimulationResult] = useState({ totalHuella: 0, status: 'idle', msg: 'ESPERANDO DATOS...' });

        // Gestión de filas
        const addRow = () => {
            setRows([...rows, { 
                id: Date.now(), name: '', origMass: '', num: '', den: '', factor: '', userMass: '', userHuella: '', status: 'neutral' 
            }]);
        };

        const removeRow = (id) => {
            if(rows.length > 1) setRows(rows.filter(r => r.id !== id));
        };

        const updateRow = (id, field, value) => {
            setRows(rows.map(r => r.id === id ? { ...r, [field]: value, status: 'neutral' } : r));
            setSimulationResult({ ...simulationResult, status: 'idle', msg: 'DATOS MODIFICADOS. REQUIERE NUEVA SIMULACIÓN.' });
        };

        // LÓGICA DE VERIFICACIÓN (LA ALQUIMIA)
        const runSimulation = () => {
            let allCorrect = true;
            let totalCalculatedHuella = 0;
            let errorsFound = [];

            const verifiedRows = rows.map(row => {
                // Parsear datos (reemplazando comas por puntos)
                const oMass = parseFloat(row.origMass.replace(',', '.'));
                const num = parseFloat(row.num);
                const den = parseFloat(row.den);
                const factor = parseFloat(row.factor.replace(',', '.'));
                const uMass = parseFloat(row.userMass.replace(',', '.'));
                const uHuella = parseFloat(row.userHuella.replace(',', '.'));

                // Validación de campos vacíos
                if ([oMass, num, den, factor, uMass, uHuella].some(isNaN)) {
                    return { ...row, status: 'error' };
                }

                // 1. Cálculo de Nueva Masa (Alquimia Fraccionaria)
                // Fórmula: MasaOriginal * (Num / Den)
                const realNewMass = oMass * (num / den);

                // 2. Cálculo de Nueva Huella
                // Fórmula: NuevaMasa * Factor
                const realNewHuella = realNewMass * factor;

                totalCalculatedHuella += realNewHuella;

                // Comprobación con tolerancia (para redondeos)
                const massDiff = Math.abs(realNewMass - uMass);
                const huellaDiff = Math.abs(realNewHuella - uHuella);

                // Criterio de éxito: Masa precisa (0.001 kg) y Huella razonable (1 L)
                if (massDiff <= 0.005 && huellaDiff <= 1) {
                    return { ...row, status: 'success' };
                } else {
                    allCorrect = false;
                    return { ...row, status: 'error' };
                }
            });

            setRows(verifiedRows);

            if (allCorrect) {
                setSimulationResult({
                    totalHuella: totalCalculatedHuella.toFixed(1),
                    status: 'success',
                    msg: '✅ TRANSMUTACIÓN ESTABLE. CÁLCULOS PERFECTOS.'
                });
            } else {
                setSimulationResult({
                    totalHuella: '---',
                    status: 'error',
                    msg: '❌ FALLO EN LA MATRIZ. REVISA LAS CELDAS ROJAS.'
                });
            }
        };

        // Renderizado de iconos Lucide
        useEffect(() => {
            lucide.createIcons();
        }, [rows, simulationResult]);

        return (
            <div className="lab-container">
                <div className="header">
                    <div className="brand">
                        <i data-lucide="flask-conical"></i> GAIA ALCHEMY LAB <span style={{fontSize:'0.8rem', opacity:0.7}}>v3.0</span>
                    </div>
                    <div style={{fontSize:'0.8rem', color:'var(--text-neon)'}}>
                        MODO: VERIFICACIÓN
                    </div>
                </div>

                <div className="experiment-area">
                    <table>
                        <thead>
                            <tr>
                                <th style={{width:'20%'}}>INGREDIENTE</th>
                                <th style={{width:'10%'}}>MASA ORIG.<br />(Kg)</th>
                                <th style={{width:'15%'}}>ESTRATEGIA<br />(Fracción)</th>
                                <th style={{width:'10%'}}>FACTOR<br />(L/Kg)</th>
                                <th style={{width:'15%', color:'#ffd700'}}>TU NUEVA MASA<br />(Kg)</th>
                                <th style={{width:'15%', color:'#ffd700'}}>TU NUEVA HUELLA<br />(L)</th>
                                <th style={{width:'5%'}}></th>
                            </tr>
                        </thead>
                        <tbody>
                            {rows.map(row => (
                                <tr key={row.id}>
                                    <td>
                                        <input type="text" placeholder="Ej: Lentejas" value={row.name} onChange={(e)=>updateRow(row.id, 'name', e.target.value)} />
                                    </td>
                                    <td>
                                        <input type="number" placeholder="0.000" value={row.origMass} onChange={(e)=>updateRow(row.id, 'origMass', e.target.value)} />
                                    </td>
                                    <td>
                                        <div className="fraction-group">
                                            <input type="number" placeholder="N" style={{textAlign:'center'}} value={row.num} onChange={(e)=>updateRow(row.id, 'num', e.target.value)} />
                                            <span className="fraction-divider">/</span>
                                            <input type="number" placeholder="D" style={{textAlign:'center'}} value={row.den} onChange={(e)=>updateRow(row.id, 'den', e.target.value)} />
                                        </div>
                                    </td>
                                    <td>
                                        <input type="number" placeholder="L/Kg" value={row.factor} onChange={(e)=>updateRow(row.id, 'factor', e.target.value)} />
                                    </td>
                                    {/* INPUTS DE USUARIO CON VALIDACIÓN VISUAL */}
                                    <td>
                                        <input 
                                            type="number" 
                                            placeholder="Resultado" 
                                            className={row.status === 'success' ? 'valid' : row.status === 'error' ? 'invalid' : ''}
                                            value={row.userMass} 
                                            onChange={(e)=>updateRow(row.id, 'userMass', e.target.value)} 
                                        />
                                    </td>
                                    <td>
                                        <input 
                                            type="number" 
                                            placeholder="Resultado"
                                            className={row.status === 'success' ? 'valid' : row.status === 'error' ? 'invalid' : ''}
                                            value={row.userHuella} 
                                            onChange={(e)=>updateRow(row.id, 'userHuella', e.target.value)} 
                                        />
                                    </td>
                                    <td>
                                        <button className="btn-del" onClick={() => removeRow(row.id)}><i data-lucide="trash-2"></i></button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>

                    <button className="btn btn-add" onClick={addRow}>+ AÑADIR COMPONENTE</button>
                </div>

                <div className="results-panel">
                    <div className="status-box">
                        <span style={{color:'#aaa', fontSize:'0.8rem'}}>ESTADO DE LA SIMULACIÓN</span>
                        <div className={`status-msg ${simulationResult.status === 'success' ? 'pass' : simulationResult.status === 'error' ? 'fail' : ''}`} style={{display:'flex', alignItems:'center', justifyContent:'center', marginTop:'10px', gap:'10px'}}>
                            {simulationResult.status === 'success' && <i data-lucide="check"></i>}
                            {simulationResult.status === 'error' && <i data-lucide="alert-triangle"></i>}
                            {simulationResult.msg}
                        </div>
                    </div>

                    <div>
                        <button className="btn btn-verify" onClick={runSimulation}>
                            <i data-lucide="atom" style={{verticalAlign:'middle', marginRight:'10px'}}></i>
                            INICIAR TRANSMUTACIÓN
                        </button>

                        {simulationResult.status === 'success' && (
                            <div style={{textAlign:'right', marginTop:'15px'}}>
                                <span style={{color:'var(--text-neon)'}}>IMPACTO HÍDRICO FINAL:</span>
                                <span className="big-stat">{simulationResult.totalHuella} L</span>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<AlchemyLab />);
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
